Node* deleteNode(Node* root, int target) {
    if (!root) return nullptr;
    if (target < root->value) root->left = deleteNode(root->left, target);
    else if (target > root->value) root->right = deleteNode(root->right, target);
    else {
        // Case 1: Leaf node
        if (!root->left && !root->right) { delete root; return nullptr; }
        // Case 2: One child
        if (!root->left) { Node* temp = root->right; delete root; return temp; }
        if (!root->right) { Node* temp = root->left; delete root; return temp; }
        // Case 3: Two children (Inorder Successor)
        Node* succ = minValueNode(root->right);
        root->value = succ->value;
        root->right = deleteNode(root->right, succ->value);
    }
    return root;
}

