void dijkstra(int src, const Graph& g) {
    // Requires non-negative weights
    std::vector<int> dist(g.V, INF);
    std::priority_queue<Pair, vector<Pair>, greater<Pair>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue; // skip stale
        for (const auto& e : g.adj[u]) {
            int v = e.to, w = e.weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
}

