codes.maze:
bool solveMaze(vector<vector<int>>& grid,
               int row, int col,
               int goalRow, int goalCol,
               vector<pair<int,int>>& path) {
    int rows = grid.size(), cols = grid[0].size();
    // Bounds and wall check
    if (row < 0 || row >= rows || col < 0 || col >= cols)
        return false;
    if (grid[row][col] == 1)  // wall
        return false;
    if (grid[row][col] == 2)  // already visited
        return false;
    // Mark visited and push to candidate path
    grid[row][col] = 2;
    path.push_back({row, col});
    // Goal check
    if (row == goalRow && col == goalCol)
        return true;
    // Explore neighbours: Down, Right, Up, Left
    int dr[] = {1, 0, -1, 0};
    int dc[] = {0, 1,  0,-1};
    for (int d = 0; d < 4; d++) {
        if (solveMaze(grid, row+dr[d], col+dc[d],
                      goalRow, goalCol, path))
            return true;
    }
    // Backtrack
    grid[row][col] = 0;
    path.pop_back();
    return false;
}

codes.n-queens:
bool solveNQueens(int row, int n,
                  vector<int>& board,
                  vector<bool>& cols,
                  vector<bool>& diag1,
                  vector<bool>& diag2,
                  int& solutions) {
    if (row == n) {
        // All queens placed successfully
        solutions++;
        return true; // stop after first if findAll=false
    }
    for (int col = 0; col < n; col++) {
        // Check column and diagonal conflicts
        if (cols[col] || diag1[row-col+n-1] || diag2[row+col])
            continue;
        // Place queen
        board[row] = col;
        cols[col] = diag1[row-col+n-1] = diag2[row+col] = true;
        // Recurse to next row
        if (solveNQueens(row+1, n, board, cols, diag1, diag2, solutions))
            return true;
        // Backtrack: remove queen
        board[row] = -1;
        cols[col] = diag1[row-col+n-1] = diag2[row+col] = false;
    }
    return false;
}

