int maxSubarraySumFixed(const std::vector<int>& arr, int k) {
    int n = static_cast<int>(arr.size());
    if (k <= 0 || k > n) return 0;
    int windowSum = 0;
    for (int i = 0; i < k; ++i) {
        windowSum += arr[i];
    }
    int maxSum = windowSum;
    for (int i = k; i < n; ++i) {
        windowSum += arr[i] - arr[i - k]; // Slide window: add incoming, subtract outgoing
        if (windowSum > maxSum) {
            maxSum = windowSum;
        }
    }
    return maxSum;
}

