    std::unordered_map<long long, int> prefixFreq;
    prefixFreq[0] = 1; // Empty prefix has sum 0
    long long runningSum = 0;
    int count = 0;
    for (int x : nums) {
        runningSum += x;
        long long needed = runningSum - k;
        if (prefixFreq.count(needed)) {
            count += prefixFreq[needed];
        }
        prefixFreq[runningSum]++;
    }
    return count;
}

