ListNode* detectCycleEntry(ListNode *head) {
    if (!head || !head->next) return nullptr;
    ListNode *slow = head, *fast = head;
    bool hasLoop = false;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) { hasLoop = true; break; }
    }
    if (!hasLoop) return nullptr;
    slow = head; // Reset slow to head
    while (slow != fast) {
        slow = slow->next;
        fast = fast->next;
    }
    return slow; // Meeting point is cycle entry
}

