std::vector<int> nextGreaterElements(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> result(n, -1);
    std::stack<int> st; // Monotonic decreasing stack storing indices
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[i] > nums[st.top()]) {
            result[st.top()] = nums[i]; // nums[i] is next greater for st.top()
            st.pop();
        }
        st.push(i);
    }
    return result;
}

